import { LocalStorage } from './localStorage.js';

/**
 * Media storage contract. Every backend implements these three methods:
 *   put(key, buffer, { contentType })  -> stores bytes under a server-generated key
 *   remove(key)                        -> deletes; missing keys are not an error
 *   publicUrl(key)                     -> URL the browser can load
 *
 * Keys are generated by the server (see services/hotelImage.service.js), never taken from client
 * filenames. To add S3, Cloudinary or GCS, implement the same three methods and select it here.
 */
let instance;

export function getStorage() {
  if (!instance) {
    const driver = process.env.MEDIA_STORAGE ?? 'local';
    if (driver !== 'local') {
      throw new Error(`Unsupported MEDIA_STORAGE driver "${driver}". Only "local" is implemented.`);
    }
    instance = new LocalStorage({
      directory: process.env.MEDIA_DIR ?? 'uploads',
      publicBasePath: process.env.MEDIA_BASE_PATH ?? '/media',
    });
  }
  return instance;
}

/** Test seam: lets the suite point storage at a temporary directory. */
export function resetStorageForTests() {
  instance = undefined;
}
